"""Bounded policy parser, independent of the service registry.

Parsing is also used for envelope occurrence accounting.  Registry lookup is
intentionally a later compilation step: a well-formed unknown name still counts.
"""
import re
from dataclasses import dataclass

_WS = re.compile(r'[ \t\f\r\n]*')
_IDENT = re.compile(r'[A-Za-z][A-Za-z0-9]*')
_ATOMS = ('match', 'startswith', 'endswith', 'contains')


class PolicyError(ValueError):
    pass


@dataclass(slots=True)
class Policy:
    rules: list
    atoms: int
    symbols: int
    names: set


class _Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.atoms = self.symbols = self.complex = 0
        self.nonliteral = set()
        self.names = set()

    def ws(self):
        self.pos = _WS.match(self.text, self.pos).end()

    def take(self, token):
        self.ws()
        if not self.text.startswith(token, self.pos):
            raise PolicyError('syntax')
        self.pos += len(token)

    def path(self):
        self.take('(')
        self.ws()
        path = []
        if self.text.startswith(')', self.pos):
            self.pos += 1
            return ()
        while True:
            self.ws()
            match = _IDENT.match(self.text, self.pos)
            if match is None or len(match[0]) > 24:
                raise PolicyError('name')
            name = match[0]
            self.pos = match.end()
            path.append(name)
            self.names.add(name)
            if len(path) > 16:
                raise PolicyError('path length')
            self.ws()
            if self.text.startswith(')', self.pos):
                self.pos += 1
                return tuple(path)
            self.take(',')

    def predicate(self, depth):
        if depth > 16:
            raise PolicyError('depth')
        self.ws()
        if self.text.startswith('(', self.pos):
            self.pos += 1
            left = self.predicate(depth + 1)
            self.ws()
            if self.text.startswith('and', self.pos):
                op = 'and'
            elif self.text.startswith('or', self.pos):
                op = 'or'
            else:
                raise PolicyError('binary operator')
            self.pos += len(op)
            right = self.predicate(depth + 1)
            self.take(')')
            return (op, left, right)
        if self.text.startswith('not', self.pos):
            self.pos += 3
            self.take('(')
            child = self.predicate(depth + 1)
            self.take(')')
            return ('not', child)
        for op in _ATOMS:
            if self.text.startswith(op, self.pos):
                self.pos += len(op)
                path = self.path()
                self.atoms += 1
                self.symbols += len(path)
                if self.atoms > 32768 or self.symbols > 65536:
                    raise PolicyError('occurrences')
                if op != 'match':
                    if len(path) > 4:
                        raise PolicyError('nonliteral path')
                    self.nonliteral.add((op, path))
                    if len(self.nonliteral) > 4:
                        raise PolicyError('nonliteral atoms')
                return (op, path)
        raise PolicyError('predicate')

    def parse(self):
        rules = []
        while True:
            self.ws()
            if self.pos == len(self.text):
                return Policy(rules, self.atoms, self.symbols, self.names)
            old_atoms = self.atoms
            predicate = self.predicate(1)
            if predicate[0] != 'match':
                self.complex += 1
                if self.complex > 8 or self.atoms - old_atoms > 32:
                    raise PolicyError('complex rules')
            self.ws()
            if self.text.startswith('allow', self.pos):
                action = 'allow'
            elif self.text.startswith('drop', self.pos):
                action = 'drop'
            else:
                raise PolicyError('action')
            self.pos += len(action)
            self.take(';')
            rules.append((predicate, action))


def parse(text, names=None):
    policy = _Parser(text).parse()
    if names is not None and not policy.names <= set(names):
        raise PolicyError('unknown service')
    return policy
