"""Language compilation without repeated pairwise unions of literal DFAs.

All exact paths form a finite trie. A history still in that trie determines its
nonliteral state uniquely; after leaving it no exact atom can ever match again.
Only the (at most four) short nonliteral atoms need a DFA product. Minimize that
small cyclic core first, then intern trie residuals bottom-up against the core.
This yields the full minimal machine in linear trie space and time.
"""
from syntax import PolicyError, parse


def _atom_machine(op, path, width):
    length = len(path)
    if not length:
        return [[0] * width], [True]
    if op == 'startswith':
        fail = length + 1
        rows = [[(q + 1 if a == path[q] else fail) for a in range(width)]
                for q in range(length)]
        rows += [[length] * width, [fail] * width]
        return rows, [q == length for q in range(length + 2)]
    # KMP prefix lengths implement suffix and contiguous-subsequence predicates.
    prefix = [0] * length
    for i in range(1, length):
        j = prefix[i - 1]
        while j and path[i] != path[j]:
            j = prefix[j - 1]
        if path[i] == path[j]:
            j += 1
        prefix[i] = j
    rows = []
    for q in range(length + 1):
        row = []
        for a in range(width):
            if op == 'contains' and q == length:
                row.append(length)
                continue
            j = prefix[length - 1] if q == length else q
            while j and path[j] != a:
                j = prefix[j - 1]
            if path[j] == a:
                j += 1
            row.append(j)
        rows.append(row)
    return rows, [q == length for q in range(length + 1)]


def _product(atoms, columns, width):
    machines = [_atom_machine(op, tuple(columns[x] for x in path), width)
                for op, path in atoms]
    start = (0,) * len(machines)
    states = [start]
    index = {start: 0}
    rows, values = [], []
    for state in states:
        value = sum(1 << i for i, q in enumerate(state) if machines[i][1][q])
        values.append(value)
        row = []
        for a in range(width):
            target = tuple(machines[i][0][q][a] for i, q in enumerate(state))
            found = index.get(target)
            if found is None:
                found = len(states)
                index[target] = found
                states.append(target)
            row.append(found)
        rows.append(row)
    return rows, values


def _minimize_core(rows, accept):
    """Moore refinement on the bounded, short-pattern core only."""
    classes = [int(flag) for flag in accept]
    old_count = len(set(classes))
    while True:
        signatures = {}
        refined = []
        representatives = []
        for q, row in enumerate(rows):
            key = (accept[q], tuple(classes[t] for t in row))
            group = signatures.get(key)
            if group is None:
                group = len(signatures)
                signatures[key] = group
                representatives.append(q)
            refined.append(group)
        classes = refined
        if len(signatures) == old_count:
            break
        old_count = len(signatures)
    minimal_rows = [tuple(classes[t] for t in rows[q]) for q in representatives]
    minimal_accept = [accept[q] for q in representatives]
    # Mark core residuals with a nonempty future language.
    reverse = [[] for _ in minimal_rows]
    for q, row in enumerate(minimal_rows):
        for target in set(row):
            reverse[target].append(q)
    live = minimal_accept.copy()
    queue = [q for q, flag in enumerate(live) if flag]
    for q in queue:
        for source in reverse[q]:
            if not live[source]:
                live[source] = True
                queue.append(source)
    return classes, minimal_rows, minimal_accept, live


def compile_policy(policy, registry):
    """Return (START class, rows, acceptance flags, live flags)."""
    if isinstance(policy, str):
        policy = parse(policy)
    ordered = sorted(registry, key=lambda s: s['label'])
    columns = {s['name']: i for i, s in enumerate(ordered)}
    if not policy.names <= columns.keys():
        raise PolicyError('unknown service')
    width = len(ordered)
    records = {}  # literal path -> simple allow/drop flags
    expressions = []
    nonlinear = {}
    complex_paths = set()
    for predicate, action in policy.rules:
        if predicate[0] == 'match':
            path = predicate[1]
            records[path] = records.get(path, 0) | (1 if action == 'allow' else 2)
        else:
            expressions.append((predicate, action))
            stack = [predicate]
            while stack:
                node = stack.pop()
                op = node[0]
                if op == 'match':
                    complex_paths.add(node[1])
                    records.setdefault(node[1], 0)
                elif op in ('startswith', 'endswith', 'contains'):
                    nonlinear.setdefault(node, len(nonlinear))
                else:
                    stack.extend(node[1:])
    # Truth tables are tiny integers, one bit for each nonliteral valuation.
    valuations = 1 << len(nonlinear)
    universe = (1 << valuations) - 1
    atom_masks = {atom: sum(1 << v for v in range(valuations) if v & (1 << i))
                  for atom, i in nonlinear.items()}

    def evaluate(node, exact):
        op = node[0]
        if op == 'match':
            return universe if node[1] == exact else 0
        if op == 'not':
            return universe ^ evaluate(node[1], exact)
        if op == 'and':
            return evaluate(node[1], exact) & evaluate(node[2], exact)
        if op == 'or':
            return evaluate(node[1], exact) | evaluate(node[2], exact)
        return atom_masks[node]

    def masks(exact):
        allow = drop = 0
        for predicate, action in expressions:
            value = evaluate(predicate, exact)
            if action == 'allow':
                allow |= value
            else:
                drop |= value
        return allow, drop

    default_allow, default_drop = masks(None)
    default_mask = default_allow & (universe ^ default_drop)
    special_masks = {path: masks(path) for path in complex_paths}
    product_rows, values = _product(nonlinear, columns, width)
    base_accept = [bool(default_mask & (1 << v)) for v in values]
    product_classes, rows, accept, live = _minimize_core(product_rows, base_accept)
