from compiler.compiler import compile_policy
from syntax import PolicyError

DENY = 4294967295


def create(policy, registry):
    start, rows, accept, live = compile_policy(policy, registry)
    order = [start]
    labels = {start: 0}
    image_rows, image_accept = [], []
    for source in order:
        image_accept.append(accept[source])
        row = []
        for target in rows[source]:
            if not live[target]:
                row.append(DENY)
                continue
            label = labels.get(target)
            if label is None:
                label = len(order)
                if label >= 8192:
                    raise PolicyError('image rows')
                labels[target] = label
                order.append(target)
            row.append(label)
        image_rows.append(row)
    return {'accept': image_accept, 'rows': image_rows}
