"""Strict JSON envelope, static job validation, then independent atomic replay."""
import json
import math
import re
import sys
from ebpf.helper import Agent, REJECTED
from syntax import parse, PolicyError

U32 = 4294967295
LIMITS = {'images': 16, 'cells': 262144, 'units': 1024, 'contexts': 32768,
          'connections': 4096, 'packets': 32768, 'files': 8192}
NAME = re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\Z')
SCHEMA = {
    'stage': {'epoch': 'positive', 'policy': 'text'},
    'commit': {'epoch': 'positive'}, 'retire': {'epoch': 'positive'},
    'spawn': {'unit': 'unit', 'service': 'name'},
    'clone': {'parent': 'unit', 'child': 'unit'}, 'exit': {'unit': 'unit'},
    'begin': {'unit': 'unit', 'rid': 'positive'},
    'finish': {'unit': 'unit', 'rid': 'positive'},
    'open': {'connection': 'pair'}, 'close': {'connection': 'pair'},
    'send': {'unit': 'unit', 'rid': 'positive', 'connection': 'pair',
             'stream': 'positive', 'destination': 'name'},
    'recv': {'unit': 'unit', 'rid': 'positive', 'connection': 'pair',
             'stream': 'positive', 'wire': 'wire'},
    'store': {'unit': 'unit', 'rid': 'positive', 'file': 'pair'},
    'load': {'unit': 'unit', 'rid': 'positive', 'file': 'pair'},
    'unlink': {'file': 'pair'}, 'inspect': {}}
FIELD_SETS = {op: set(fields) | {'op'} for op, fields in SCHEMA.items()}


class Invalid(ValueError):
    pass


def require(ok):
    if not ok:
        raise Invalid()


def integer(value, lo=1, hi=U32):
    return type(value) is int and lo <= value <= hi


def typed(value, kind):
    if kind == 'positive':
        return integer(value)
    if kind == 'name':
        return type(value) is str and NAME.fullmatch(value) is not None
    if kind == 'text':
        if type(value) is not str:
            return False
        value.encode('utf-8')  # Unpaired surrogates are job errors, not JSON errors.
        return True
    if kind == 'wire':
        return value is None or type(value) is str and len(value) <= 96
    if kind == 'pair':
        return type(value) is list and len(value) == 2 and all(integer(x) for x in value)
    if kind == 'unit':
        return (type(value) is list and len(value) == 3 and integer(value[0], 0)
                and integer(value[1]) and integer(value[2]))
    return False


def validate(job):
    """Only structure/types/static bounds; never inspect policy grammar here."""
    require(type(job) is dict and set(job) == {'services', 'limits', 'events'})
    services, limits, events = job['services'], job['limits'], job['events']
    require(type(services) is list and 1 <= len(services) <= 16)
    names, labels = set(), set()
    for service in services:
        require(type(service) is dict and set(service) == {'name', 'label'})
        require(typed(service['name'], 'name') and integer(service['label'], 1, U32 - 1))
        require(service['name'] not in names and service['label'] not in labels)
        names.add(service['name'])
        labels.add(service['label'])
    require(type(limits) is dict and set(limits) == set(LIMITS))
    for key, value in limits.items():
        require(integer(value, 1, LIMITS[key]))
    require(type(events) is list and len(events) <= 200000)
    policy_bytes = stages = 0
    for event in events:
        require(type(event) is dict and type(event.get('op')) is str and event['op'] in SCHEMA)
        op = event['op']
        require(set(event) == FIELD_SETS[op])
        for key, kind in SCHEMA[op].items():
            require(typed(event[key], kind))
        if op == 'stage':
            stages += 1
            policy_bytes += len(event['policy'].encode('utf-8'))
    return len(events), policy_bytes, stages


def unique(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result)
        result[key] = value
    return result


def invalid_constant(text):
    raise Invalid()


def float_number(text):
    value = float(text)
    require(math.isfinite(value))
    return value


def check_json_nesting(text):
    depth = 0
    quoted = escaped = False
    for char in text:
        if quoted:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                quoted = False
        elif char == '"':
            quoted = True
        elif char in '[{':
            depth += 1
            require(depth <= 64)
        elif char in ']}':
            depth -= 1
            require(depth >= 0)
    require(depth == 0 and not quoted)


def solve(data):
    try:
        require(len(data) <= 24 * 1024**2)
        text = data.decode('utf-8')
        check_json_nesting(text)
        request = json.loads(text, object_pairs_hook=unique,
                             parse_constant=invalid_constant, parse_float=float_number)
        require(type(request) is dict and set(request) == {'jobs'} and
                type(request['jobs']) is list and len(request['jobs']) <= 4)
    except (ValueError, RecursionError):
        return {'error': 'invalid'}
    validity = []
    totals = [0, 0, 0]
    for job in request['jobs']:
        try:
            counts = validate(job)
        except (ValueError, TypeError):
            validity.append(False)
        else:
            validity.append(True)
            totals = [a + b for a, b in zip(totals, counts)]
    if totals[0] > 200000 or totals[1] > 8 * 1024**2 or totals[2] > 16:
        return {'error': 'invalid'}

    # Count syntactically bounded policies regardless of registry or replay fate.
    parsed = {}
    atoms = symbols = 0
    for job, valid in zip(request['jobs'], validity):
        if not valid:
            continue
        for event in job['events']:
            if event['op'] != 'stage':
                continue
            text = event['policy']
            if text not in parsed:
                try:
                    parsed[text] = parse(text)
                except PolicyError:
                    parsed[text] = None
            policy = parsed[text]
            if policy is not None:
                atoms += policy.atoms
                symbols += policy.symbols
    if atoms > 32768 or symbols > 65536:
        return {'error': 'invalid'}

    results = []
    for job, valid in zip(request['jobs'], validity):
        if not valid:
            results.append({'error': 'invalid'})
            continue
        agent = Agent(job['services'], job['limits'])
        outcomes = []
        for event in job['events']:
            if event['op'] == 'stage':
                policy = parsed[event['policy']]
                outcomes.append(REJECTED if policy is None else agent.event(event, policy))
            else:
                outcomes.append(agent.event(event))
        results.append({'events': outcomes})
    return {'results': results}


if __name__ == '__main__':
    result = solve(sys.stdin.buffer.read(24 * 1024**2 + 1))
    sys.stdout.write(json.dumps(result, separators=(',', ':'), ensure_ascii=True) + '\n')
